    # First, we need to check if we can create a quad precision dtype
    # This might be QuadPrecDType or another quad precision type
    try:
        QuadPrecDType = np.float128
    except AttributeError:
        try:
            QuadPrecDType = np.longdouble
        except AttributeError:
            QuadPrecDType = None

    if QuadPrecDType is None:
        raise AttributeError("Quad precision dtype not available")

